import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long d = Long.parseLong(next());
        long[][] a = new long[(int) n][2];
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                a[i][j] = Long.parseLong(next());
            }
        }
        long[][] b = new long[(int) m][2];
        for (int i = 0; i < b.length; i++) {
            for (int j = 0; j < b[i].length; j++) {
                b[i][j] = Long.parseLong(next());
            }
        }

        int na = (int) n, nb = (int) m;
        long[] ka = new long[na];
        long[] kb = new long[nb];
        for (int x = 0; x < na; x++) ka[x] = (a[x][0] << 30) + a[x][1];
        for (int x = 0; x < nb; x++) kb[x] = (b[x][0] << 30) + b[x][1];
        Arrays.sort(ka);
        Arrays.sort(kb);
        long mask = (1L << 30) - 1;
        int i = 0, j = 0;
        String answer = "-1";
        while (i < na && j < nb) {
            long sa = ka[i] >> 30, ea = ka[i] & mask;
            long sb = kb[j] >> 30, eb = kb[j] & mask;
            long lo = Math.max(sa, sb);
            long hi = Math.min(ea, eb);
            if (hi - lo >= d) {
                answer = lo + " " + (lo + d);
                break;
            }
            if (ea < eb) i++;
            else j++;
        }
        System.out.println(answer);
    }
}
